// src/components/VendorDashboard.js
import React, { useState, useEffect } from "react";
import "./VendorDashboard.css";
import {
  getProductsByVendor,
  createProduct,
  updateProduct,
  deleteProductById,
  getOrdersByVendor,
  updateOrderStatus,
} from "../utils/api";

export default function VendorDashboard({ vendor }) {
  const [products, setProducts] = useState([]);
  const [orders, setOrders] = useState([]);
  const [form, setForm] = useState({
    id: null,
    name: "",
    description: "",
    price: "",
    stockQuantity: "",
    category: "",
    imageUrl: "",
  });
  const [editing, setEditing] = useState(false);

  // Fetch products and orders
  const fetchProducts = async () => {
    if (!vendor) return;
    const data = await getProductsByVendor(vendor.id);
    setProducts(data);
  };

  const fetchOrders = async () => {
    if (!vendor) return;
    const data = await getOrdersByVendor(vendor.id);
    setOrders(data);
  };

  useEffect(() => {
    fetchProducts();
    fetchOrders();
  }, [vendor]);

  // Product form handling
  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm({ ...form, [name]: value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      if (editing) {
        await updateProduct(form.id, { ...form, vendor });
      } else {
        await createProduct({ ...form, vendor });
      }
      setForm({
        id: null,
        name: "",
        description: "",
        price: "",
        stockQuantity: "",
        category: "",
        imageUrl: "",
      });
      setEditing(false);
      fetchProducts();
    } catch (err) {
      console.error(err);
      alert("Error saving product");
    }
  };

  const handleEdit = (product) => {
    setForm(product);
    setEditing(true);
  };

  const handleDelete = async (id) => {
    if (window.confirm("Are you sure?")) {
      await deleteProductById(id);
      fetchProducts();
    }
  };

  // Update order status
  const handleStatusChange = async (orderId, newStatus) => {
    try {
      await updateOrderStatus(orderId, newStatus);
      fetchOrders();
    } catch (err) {
      console.error(err);
      alert("Error updating order status");
    }
  };

  return (
    <div className="vendor-dashboard">
      <div style={{ padding: "20px" }}>
        <h2>Welcome, {vendor?.name}</h2>

        {/* Product Form */}
        <h3>{editing ? "Edit Product" : "Add Product"}</h3>
        <form onSubmit={handleSubmit} style={{ marginBottom: "20px" }}>
          <input
            name="name"
            placeholder="Name"
            value={form.name}
            onChange={handleChange}
            required
          />
          <input
            name="description"
            placeholder="Description"
            value={form.description}
            onChange={handleChange}
          />
          <input
            name="price"
            placeholder="Price"
            type="number"
            step="0.01"
            value={form.price}
            onChange={handleChange}
            required
          />
          <input
            name="stockQuantity"
            placeholder="Stock Quantity"
            type="number"
            value={form.stockQuantity}
            onChange={handleChange}
            required
          />
          <input
            name="category"
            placeholder="Category"
            value={form.category}
            onChange={handleChange}
            required
          />
          <input
            name="imageUrl"
            placeholder="Image URL"
            value={form.imageUrl}
            onChange={handleChange}
          />
          <button type="submit">{editing ? "Update" : "Add"}</button>
          {editing && (
            <button
              type="button"
              onClick={() => {
                setForm({
                  id: null,
                  name: "",
                  description: "",
                  price: "",
                  stockQuantity: "",
                  category: "",
                  imageUrl: "",
                });
                setEditing(false);
              }}
            >
              Cancel
            </button>
          )}
        </form>

        {/* Product List */}
        <h3>Your Products</h3>
        <table border="1" cellPadding="10">
          <thead>
            <tr>
              <th>Name</th>
              <th>Price</th>
              <th>Stock</th>
              <th>Category</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {products.length === 0 && (
              <tr>
                <td colSpan="5">No products found</td>
              </tr>
            )}
            {products.map((p) => (
              <tr key={p.id}>
                <td>{p.name}</td>
                <td>{p.price}</td>
                <td>{p.stockQuantity}</td>
                <td>{p.category}</td>
                <td>
                  <button onClick={() => handleEdit(p)}>Edit</button>
                  <button onClick={() => handleDelete(p.id)}>Delete</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>

        {/* Orders List */}
        <h3>Orders for Your Products</h3>
        <table border="1" cellPadding="10">
          <thead>
            <tr>
              <th>Order ID</th>
              <th>Customer</th>
              <th>Email</th>
              <th>Total</th>
              <th>Status</th>
              <th>Update Status</th>
            </tr>
          </thead>
          <tbody>
            {orders.length === 0 && (
              <tr>
                <td colSpan="6">No orders found</td>
              </tr>
            )}
            {orders.map((order) => (
              <tr key={order.id}>
                <td>{order.id}</td>
                <td>{order.customerName}</td>
                <td>{order.customerEmail}</td>
                <td>{order.totalAmount}</td>
                <td>{order.status}</td>
                <td>
                  <select
                    value={order.status}
                    onChange={(e) =>
                      handleStatusChange(order.id, e.target.value)
                    }
                  >
                    <option value="PENDING">PENDING</option>
                    <option value="PROCESSING">PROCESSING</option>
                    <option value="SHIPPED">SHIPPED</option>
                    <option value="DELIVERED">DELIVERED</option>
                    <option value="CANCELLED">CANCELLED</option>
                  </select>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
